<?php
namespace App\Models;use Illuminate\Database\Eloquent\Model;class MenuItem extends Model{protected $fillable=['parent_id','page_id','title','url','location','target','sort','is_active'];protected $casts=['is_active'=>'boolean'];public function parent(){return $this->belongsTo(self::class,'parent_id');}public function children(){return $this->hasMany(self::class,'parent_id')->orderBy('sort');}public function page(){return $this->belongsTo(Page::class);}public function getHrefAttribute():string{if($this->page)return route('page.show',$this->page);return $this->url?:'#';}}